ALTER TABLE gyms ADD COLUMN IF NOT EXISTS archived_at timestamptz;
CREATE TABLE IF NOT EXISTS master_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email varchar(254) NOT NULL UNIQUE CHECK(lower(email)='fabio17dejesusjunior@gmail.com'),password_hash text NOT NULL,must_change_password boolean NOT NULL DEFAULT true,password_expires_at timestamptz,status varchar(20) NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS master_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),master_id uuid NOT NULL REFERENCES master_accounts(id) ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS master_sessions_lookup_idx ON master_sessions(token_hash) WHERE revoked_at IS NULL;
CREATE TABLE IF NOT EXISTS master_audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),master_id uuid REFERENCES master_accounts(id) ON DELETE SET NULL,action varchar(40) NOT NULL,gym_id uuid,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
